import { MARKET_NAMES, MODEL_NAMES, fmtNum } from "./api";
import type { Cell, FeatureResult } from "./types";

// Plain-English wording for engine results. Everything here is derived from engine fields;
// the verified claims of the written brief are always shown word for word, never rephrased.

export type RecGroup = "prioritise" | "consider" | "low" | "insufficient" | "notsold";

/** The engine's own labels stay the group names; the meaning is added in plain words. */
export const REC_INFO: Record<RecGroup, { label: string; meaning: string; tone: string }> = {
  prioritise: { label: "Prioritise", meaning: "Strong customer signal. Act on these first.", tone: "go" },
  consider: { label: "Consider", meaning: "Some customer signal. Worth planning, not urgent.", tone: "maybe" },
  low: { label: "Low priority", meaning: "Little customer signal. Park it for now.", tone: "low" },
  insufficient: { label: "Insufficient evidence", meaning: "Too little feedback to judge. Collect more before deciding.", tone: "unknown" },
  notsold: { label: "Not sold", meaning: "This series is not sold in this market.", tone: "na" },
};
export const REC_ORDER: RecGroup[] = ["prioritise", "consider", "low", "insufficient", "notsold"];

export function recGroup(rec: string): RecGroup {
  if (rec.startsWith("Prioritise")) return "prioritise";
  if (rec.startsWith("Consider")) return "consider";
  if (rec.startsWith("Low")) return "low";
  if (rec.startsWith("Not sold")) return "notsold";
  return "insufficient";
}

export const seriesName = (m: string) => MODEL_NAMES[m] ?? m;
export const marketName = (m: string) => MARKET_NAMES[m] ?? m;

export function list(items: string[]): string {
  if (items.length <= 1) return items[0] ?? "";
  return `${items.slice(0, -1).join(", ")} and ${items[items.length - 1]}`;
}

/** "5 Series in Europe and the United States; 7 Series in Europe" */
export function placesText(cells: Cell[]): string {
  const by = new Map<string, string[]>();
  for (const c of cells) by.set(c.model, [...(by.get(c.model) ?? []), marketName(c.market)]);
  return [...by.entries()].map(([m, ms]) => `${seriesName(m)} in ${list(ms)}`).join("; ");
}

export function groupCells(feature: FeatureResult): Map<RecGroup, Cell[]> {
  const g = new Map<RecGroup, Cell[]>();
  for (const c of feature.cells) {
    const k = recGroup(c.recommendation);
    g.set(k, [...(g.get(k) ?? []), c]);
  }
  return g;
}

/** One opening sentence from the strongest group the engine produced. */
export function bottomLine(feature: FeatureResult): { tone: string; text: string } {
  const g = groupCells(feature);
  const name = feature.feature;
  if (g.get("prioritise")?.length)
    return { tone: "go", text: `Customers give clear reasons to act on ${name}, first for the ${placesText(g.get("prioritise")!)}.` };
  if (g.get("consider")?.length)
    return { tone: "maybe", text: `There is a case for acting on ${name}, but it is not urgent. It is worth planning for the ${placesText(g.get("consider")!)}.` };
  if (g.get("low")?.length)
    return { tone: "low", text: `Customer feedback does not support prioritising ${name} right now.` };
  return { tone: "unknown", text: `There is not enough customer feedback to judge ${name} yet.` };
}

export const VERDICT_WORDS: Record<string, string> = {
  Good: "Customers mostly like it",
  "Leaning good": "Customers lean positive",
  Mixed: "Customers are split",
  "Leaning bad": "Customers lean negative",
  Bad: "Customers mostly complain about it",
  "Not enough data": "Too few comments to say",
};

/** Complaint index read with its 95% interval: only a clear difference is called more or fewer. */
export function complaintWords(o: FeatureResult["overall"]): string {
  const ix = fmtNum(o.complaint_index);
  if (o.ci_low > 1) return `More complaints than expected (index ${ix}; 1.00 is normal, and the difference is clear).`;
  if (o.ci_high < 1) return `Fewer complaints than expected (index ${ix}; 1.00 is normal, and the difference is clear).`;
  return `About as many complaints as expected (index ${ix}; 1.00 is normal, and the difference is within normal variation).`;
}
import { useEffect, useRef, useState } from "react";
import type { Claim, Explained, Fact } from "../types";

export const TITLES: Record<string, string> = {
  customer_evidence: "What customers say",
  market_view: "Where it matters",
  price_and_equipment: "Price and equipment today",
  risks_and_caveats: "Risks and limits of the evidence",
  next_steps: "Recommended next steps",
};

/** Citation numbers in order of first use across the brief. */
export function citationNumbers(explained: Explained | null): Map<string, number> {
  const map = new Map<string, number>();
  if (!explained) return map;
  const order = ["headline", ...Object.keys(TITLES)];
  for (const s of order)
    for (const c of explained.explanation.sections[s] ?? []) for (const id of c.fact_ids) if (!map.has(id)) map.set(id, map.size + 1);
  return map;
}

export function ClaimText({
  claim,
  numbers,
  index,
  onShowNode,
}: {
  claim: Claim;
  numbers: Map<string, number>;
  index: Map<string, Fact>;
  onShowNode: (id: string) => void;
}) {
  return (
    <p className="claim__text">
      {claim.text}{" "}
      {claim.fact_ids.map((id) => (
        <Cite key={id} n={numbers.get(id) ?? 0} fact={index.get(id)} id={id} onShowNode={onShowNode} />
      ))}
    </p>
  );
}

function Cite({ n, fact, id, onShowNode }: { n: number; fact?: Fact; id: string; onShowNode: (id: string) => void }) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (!open) return;
    const close = (e: MouseEvent | KeyboardEvent) => {
      if (e instanceof KeyboardEvent ? e.key === "Escape" : !ref.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", close);
    document.addEventListener("keydown", close);
    return () => {
      document.removeEventListener("mousedown", close);
      document.removeEventListener("keydown", close);
    };
  }, [open]);
  const src = fact?.source;
  return (
    <span className="cite" ref={ref}>
      <button type="button" className="cite__btn" aria-expanded={open} onClick={() => setOpen((o) => !o)} aria-label={`Source ${n}: ${id}`}>
        {n}
      </button>
      {open && (
        <span className="popover" role="dialog" aria-label={`Fact ${id}`}>
          <span className="popover__id">{id}</span>
          <span className="popover__text">{fact ? fact.statement : "This fact is not in the bundle."}</span>
          {src && (
            <span className="popover__src">
              {src.kind}: {src.ref}
              {src.key ? ` · ${src.key}` : ""}
              {src.page ? ` · page ${src.page}` : ""}
            </span>
          )}
          {src?.node_id && (
            <button
              type="button"
              className="textlink popover__link"
              onClick={() => {
                setOpen(false);
                onShowNode(src.node_id!);
              }}
            >
              Show in knowledge graph
            </button>
          )}
        </span>
      )}
    </span>
  );
}
import type { Claim, Explained, Fact } from "../types";

const RULE_NAMES: Record<string, string> = {
  citations: "Citations",
  numbers: "Numbers",
  labels: "Labels",
  quotes: "Quotes",
  scope: "Series / market",
  semantic: "Entailment",
};
const SECTION_NAMES: Record<string, string> = {
  headline: "Bottom line",
  customer_evidence: "Customers",
  market_view: "Markets",
  price_and_equipment: "Price",
  risks_and_caveats: "Risks",
  next_steps: "Next steps",
};

/** Agent 3's report: every claim, every check, what was rewritten and what was removed. */
export default function VerificationReport({ explained, facts }: { explained: Explained | null; facts: Fact[] }) {
  if (!explained) return <p className="small muted">The report appears once the explainer and verifier have run.</p>;
  const v = explained.verification;
  const index = new Map(facts.map((f) => [f.id, f]));
  return (
    <div className="stack-lg">
      <div className="facts-row">
        <Fig label="Verified claims" value={String(v.n_verified)} />
        <Fig label="Removed claims" value={String(v.n_removed)} />
        <Fig label="Failed in first draft" value={String(v.rewritten.length)} />
        <Fig label="Semantic checker" value={v.semantic_model ?? "–"} />
      </div>
      <p className="small measure">
        Each claim must cite facts from the decision engine. Rules check citations, numbers (at the precision written), recommendation
        and verdict labels, verbatim quotes and the series and markets named; the semantic checker then judges whether the cited facts
        entail the claim. Claims that fail are sent back for one rewrite and removed if they still fail.
      </p>
      <div className="table-scroll">
        <table className="table verify">
          <thead>
            <tr>
              <th>Status</th>
              <th>Section</th>
              <th>Claim</th>
              {v.rules.map((r) => (
                <th key={r} className="verify__rule">
                  {RULE_NAMES[r] ?? r}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {v.claims.map((c) => (
              <Row key={c.id} claim={c} rules={v.rules} index={index} />
            ))}
          </tbody>
        </table>
      </div>
      {v.rewritten.length > 0 && (
        <details>
          <summary>First-draft claims that failed and triggered the rewrite ({v.rewritten.length})</summary>
          <ul className="bullets small" style={{ marginTop: 12 }}>
            {v.rewritten.map((c) => (
              <li key={c.id}>
                “{c.text}” —{" "}
                {c.checks
                  .filter((ch) => !ch.passed)
                  .map((ch) => `${RULE_NAMES[ch.name] ?? ch.name}: ${ch.detail}`)
                  .join(" ")}
              </li>
            ))}
          </ul>
        </details>
      )}
    </div>
  );
}

function Row({ claim, rules, index }: { claim: Claim; rules: string[]; index: Map<string, Fact> }) {
  const byName = new Map(claim.checks.map((c) => [c.name, c]));
  const removed = claim.status === "removed";
  return (
    <tr className={removed ? "verify__removed" : undefined}>
      <td>
        <span className={`pill ${removed ? "pill--error" : "pill--success"}`}>{removed ? "Removed" : "Verified"}</span>
      </td>
      <td className="caption">{SECTION_NAMES[claim.section] ?? claim.section}</td>
      <td>
        <p className="verify__text">{claim.text}</p>
        <p className="caption" title={claim.fact_ids.map((i) => `${i}: ${index.get(i)?.statement ?? "unknown"}`).join("\n")}>
          Cites {claim.fact_ids.length ? claim.fact_ids.join(", ") : "nothing"}
        </p>
        {removed && (
          <p className="caption error">
            {claim.checks
              .filter((c) => !c.passed)
              .map((c) => c.detail)
              .join(" ")}
          </p>
        )}
      </td>
      {rules.map((r) => {
        const ch = byName.get(r);
        return (
          <td key={r} className="verify__cell" title={ch ? ch.detail : "Not run (an earlier check failed)"}>
            {ch ? (
              <span className={ch.passed ? "tick" : "cross"} aria-label={`${r}: ${ch.passed ? "passed" : "failed"}. ${ch.detail}`} />
            ) : (
              <span className="caption" aria-label={`${r}: not run`}>
                –
              </span>
            )}
          </td>
        );
      })}
    </tr>
  );
}

function Fig({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <p className="techfact__label">{label}</p>
      <p className="techfact__value num">{value}</p>
    </div>
  );
}
