  --g-market: #6b4fa0;
  --g-sales: #9b7fd1;
  --g-model: #dc2626;
  --g-caveat: #d97706;

  /* ---- aliases used by the existing components */
  --canvas: var(--surface-background-primary);
  --surface-soft: var(--surface-background-secondary);
  --surface-card: var(--surface-background-secondary);
  --surface-strong: #e8eaf2;
  --surface-dark: var(--stage);
  --hairline: var(--border);
  --hairline-strong: #d0d5dd;
  --ink: var(--heading);
  --body: var(--copy-text);
