export const MODEL_NAMES: Record<string, string> = { F70: "1 Series", G60: "5 Series", G70: "7 Series" };
export const SERIES_LABELS: Record<string, string> = { F70: "1 Series (F70)", G60: "5 Series (G60)", G70: "7 Series (G70)" };
