          </View>
        ))}
      </View>
      {cells.map((c) => {
        const tone = TONE[REC_INFO[recGroup(c.recommendation)].tone];
        const scored = c.score !== null && c.recommendation !== "Not sold";
        return (
          <View key={`${c.model}|${c.market}`} style={{ borderTopWidth: 0.5, borderTopColor: C.border }} wrap={false}>
