function ClaimLine({ claim, numbers, bullet = true }: { claim: Claim; numbers: Map<string, number>; bullet?: boolean }) {
  const refs = claim.fact_ids.map((id) => numbers.get(id)).filter((n): n is number => n !== undefined);
  return (
